bloomstrength.script:
'use strict';
export function update(value) {
	return 0.5 + 0.25 * Math.sin(engine.runtime);
}

text.script:
'use strict';
function pad(n) { return (n < 10 ? '0' : '') + n; }
export function update(value) {
	const now = new Date();
	return pad(now.getHours()) + ':' + pad(now.getMinutes()) + ':' + pad(now.getSeconds()) + ' ' + now.getFullYear();
}

scale.script:
'use strict';
const audio = engine.registerAudioBuffers(engine.AUDIO_RESOLUTION_16);
export function update(value) {
	return new Vec3(1, 1 + audio.average[0], 1);
}

visible.script:
'use strict';
export function mediaThumbnailChanged(event) {
	thisObject.visible = event.hasThumbnail;
}

multiply.script:
'use strict';
let animation = null;
export function init(value) {
	animation = thisObject.getAnimation();
	return value;
}
export function update(value) {
	return animation === null ? -1 : animation.frameCount;
}

text.script:
'use strict';
let title = '';
export function mediaPropertiesChanged(event) {
	title = event.title;
}
export function update(value) {
	return title;
}

origin.script:
'use strict';
let clicks = 0;
export function cursorClick(event) {
	clicks += 1;
}
export function update(value) {
	value.x = clicks;
	return value;
}

