alpha.script:
'use strict';
export function update(value) {
	return value + engine.frametime;
}

rate.script:
'use strict';
const audio = engine.registerAudioBuffers(32);
let base = 1;
export function init(value) { base = value; }
export function update() {
	return base * (0.5 + audio.left[3]);
}

visible.script:
'use strict';
let bar = null;
export function init(value) {
	bar = thisScene.createLayer('models/bar.json');
	return value;
}
export function update(value) {
	if (bar !== null) bar.origin = new Vec3(engine.runtime, 0, 0);
	return bar !== null;
}

'use strict';
export var scriptProperties = createScriptProperties()
	.addCheckbox({ name: 'show', label: 'Show', value: false })
	.finish();
let userFlag = false;
export function applyUserProperties(changed) {
	if (changed.flag !== undefined) userFlag = changed.flag;
}
export function update(value) {
	return scriptProperties.show && userFlag;
}
